class Solution {
    public boolean findRotation(int[][] mat, int[][] target) {
        int n = mat.length;
        for (int rot = 0; rot < 4; ++rot) {
            boolean ok = true;
            for (int i = 0; i < n && ok; ++i) {
                for (int j = 0; j < n; ++j) {
                    int x, y;
                    if (rot == 0) {
                        x = i;
                        y = j;
                    } else if (rot == 1) {
                        x = n - 1 - j;
                        y = i;
                    } else if (rot == 2) {
                        x = n - 1 - i;
                        y = n - 1 - j;
                    } else {
                        x = j;
                        y = n - 1 - i;
                    }
                    if (mat[x][y] != target[i][j]) {
                        ok = false;
                        break;
                    }
                }
            }
            if (ok) return true;
        }
        return false;
    }
}

