class Solution:
    def findRotation(self, mat: list[list[int]], target: list[list[int]]) -> bool:
        n = len(mat)
        for rot in range(4):
            ok = True
            for i in range(n):
                if not ok:
                    break
                for j in range(n):
                    if rot == 0:
                        x, y = i, j
                    elif rot == 1:
                        x, y = n - 1 - j, i
                    elif rot == 2:
                        x, y = n - 1 - i, n - 1 - j
                    else:  # rot == 3
                        x, y = j, n - 1 - i
                    if mat[x][y] != target[i][j]:
                        ok = False
                        break
            if ok:
                return True
        return False

